/* eslint-disable react/jsx-key */
import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { MAPPER, APPMODE } from 'src/Mapper';
// @mui
import {
  Card,
  Grid,
  Box,
  Modal,
  Button,
  Container,
  Typography,
  IconButton,
  InputLabel,
  InputAdornment,
  styled,
  Stack,
} from '@mui/material';
import FormControl from '@mui/material/FormControl';
import Select from '@mui/material/Select'
import MenuItem from '@mui/material/MenuItem';
import Skeleton from '@mui/material/Skeleton';
import QRCode from 'react-qr-code';
import { axios } from '../../utils/axios';
// hooks
import useResponsive from '../../hooks/useResponsive';
// components
import { Logo } from '../../svg';
import Iconify from '../../components/iconify';
import CountryCode from '../../CountryCode'
// sections
import { LoginForm } from '../../sections/auth/login';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import InputField from '../../components/input/inputField';
import { useMyContext } from '../provider';

// ----------------------------------------------------------------------

const StyledRoot = styled('div')(({ theme }) => ({
  [theme.breakpoints.up('md')]: {
    display: 'flex',
  },
}));
const ITEM_HEIGHT = 48;
const ITEM_PADDING_TOP = 8;
const MenuProps = {
  PaperProps: {
    style: {
      maxHeight: ITEM_HEIGHT * 4.5 + ITEM_PADDING_TOP,
      width: 250,
    },
  },
};
const StyledSection = styled('div')(({ theme }) => ({
  width: '100%',
  [theme.breakpoints.up('md')]: {
    maxWidth: 480,
  },
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'center',
  boxShadow: theme.customShadows.card,
  backgroundColor: theme.palette.background.default,
}));

const StyledContent = styled('div')(({ theme }) => ({
  maxWidth: 480,
  margin: 'auto',
  [theme.breakpoints.up('md')]: {
    minHeight: '100vh',
  },
  display: 'flex',
  justifyContent: 'center',
  flexDirection: 'column',
  padding: theme.spacing(6, 0),
}));

// ----------------------------------------------------------------------

const style1 = {
  position: 'absolute',
  top: '50%',
  left: '50%',
  transform: 'translate(-50%, -50%)',
  width: 500,
  bgcolor: 'background.paper',
  boxShadow: 24,
  p: 4,
};

export default function LoginPage() {
  const data = useMyContext();
  const appLinks = data?.data?.appLinks;
  const navigate = useNavigate();
  const mdUp = useResponsive('up', 'md');
  const [open, setOpen] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [code, setCode] = useState('');
  const [phone, setPhone] = useState('');
  const [error, setError] = useState('');
  const [emailError, setEmailError] = useState('');
  const [qrLoading, setQrLoading] = useState(true);
  const isEmailDisabled = !!phone && !!code;
  const isPhoneDisabled = !!email;
  const [signInChange, setSignInChange] = useState('Email')
  const disableQr = MAPPER[window.location.host]?.appMode

  const handleChangeSelect = (event) => {
    setCode(event.target.value);
  };

  const handleChange = (e) => {
    const numericInput = e.target.value;
    setPhone(numericInput);

    if (!/^\d{10}$/.test(numericInput)) {
      setError('Invalid phone number');
    } else {
      setError('');
    }
  };

  useEffect(() => {
    if (appLinks?.playstore) {
      setQrLoading(false);
    }
  }, [appLinks?.playstore]);

  const handleMailChange = (e) => {
    const emailInput = e.target.value;
    setEmail(emailInput);

    if (!/[a-z0-9]+@[^\s@]+\.[a-z]{3}$/.test(emailInput)) {
      setEmailError('Invalid email format');
    } else if (/[!#$%^&*()_+|[\]{};:'"<>,?,]/.test(emailInput)) {
      setEmailError('Invalid email format');
    } else {
      setEmailError('');
    }
  };

  const openModalClose = () => {
    setOpen(false);
  };

  const createAdmin = async () => {

    try {
      const data = {}
      if (email) {
        data.email = email
      }
      if (code && phone) {
        data.phone = phone
        data.phoneCode = code
      }
      if (password) {
        data.password = password
      }
      const res = await axios.post('module/auth/admin', {
        ...data
      });
      if (res.status === 200) {
        setOpen(false);
        navigate('/login');
        GenerateToastConfig('Admin created successfully', 'success');
        setPhone('')
        setCode('')
        setEmail('')
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const SignIn = (method) => {
    setSignInChange(method.type)
  }

  return (
    <>
      <Helmet>
        <title> Login | Admin Panel </title>
      </Helmet>

      <StyledRoot>
        {(
          <StyledSection sx={{ display: "flex", justifyContent: "center", alignItems: "center" }}>
            <Box sx={{ px: 0, py: 3, display: 'inline-flex', justifyContent: 'center', cursor: 'pointer' }}>
              <Logo height="150px" color="red" />
              {/* <img src='/webadmin/purplerooms.png' alt='img' style={{
                height:'150px'
              }}/> */}
            </Box>
            {mdUp &&
              <>
                <Typography variant="h3">
                  Hi, Welcome Back
                </Typography>
                {/*  */}
                {/* {disableQr ? <img src="./assets/illustrations/illustration_login.png" alt="login" />: <img src="./assets/airstarQR.png" alt="login" style={{width: "200px"}}/>} */}
                {/* {qrLoading ? (
                  <Skeleton variant="rectangular" width={150} height={150} sx={{ bgcolor: "#f8f9fa" }} />
                ) : (
                  <QRCode
                    value={appLinks?.playstore}
                    size={150}
                    bgColor="#f8f9fa"
                    fgColor="#343a40"
                    level="H"
                    includeMargin
                  />
                )} */}
              </>
            }
          </StyledSection>
        )}

        <Container maxWidth="sm">
          <StyledContent>
            <Typography variant="h4" gutterBottom>
              Sign in to Admin Panel
            </Typography>
            {/* {APPMODE !== "production" ?
              <Box sx={{ padding: "20px", borderRadius: "10px", backgroundColor: "#d9d5d4", margin: "10px 0px 20px 0px" }}>
                <Typography sx={{ fontWeight: 700, fontSize: "18px", paddingBottom: "10px" }}>Demo Credentials!</Typography>
                <Stack direction='row' alignItems="center">
                  <Typography>Email </Typography>
                  <Typography sx={{ fontWeight: 700, paddingLeft: "8px" }}> : admin@airstar.com</Typography>
                </Stack>
                <Stack direction='row' alignItems="center">
                  <Typography>Password </Typography>
                  <Typography sx={{ fontWeight: 700, paddingLeft: "8px" }}> : 123456</Typography>
                </Stack>
              </Box> : ""
            } */}

            <LoginForm />
          </StyledContent>
        </Container>
      </StyledRoot>

      <Modal
        open={open}
        onClose={openModalClose}
        aria-labelledby="modal-modal-title"
        aria-describedby="modal-modal-description"
      >
        <Card sx={style1}>
          <Typography className="text-center" variant="h5" component="h4">
            Create Admin
          </Typography>
          {signInChange === "Phone" &&
            <>
              <Grid item xs={6} sx={{ padding: '0px 5px' }}>
                <InputLabel id="demo-simple-select-label">Phone code</InputLabel>
                <FormControl sx={{ marginTop: '10px' }} fullWidth>
                  <Select
                    labelId="demo-simple-select-label"
                    id="demo-simple-select"
                    value={code}
                    onChange={handleChangeSelect}
                    MenuProps={MenuProps}
                    disabled={isPhoneDisabled}
                  >
                    {CountryCode.map((data) => (
                      <MenuItem value={data.dial_code}>{data.name} &nbsp;&nbsp; {data.dial_code}</MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              <Grid item xs={6} sx={{ padding: '0px 5px' }}>
                <InputField
                  label={"Phone number"}
                  sx={{ margin: '10px 0px', width: '100%' }}
                  inputProps={{ inputMode: 'numeric', pattern: '[0-9]*' }}
                  value={phone}
                  error={!!error}
                  helperText={error}
                  onChange={handleChange}
                  inputMode="numeric"
                  disabled={isPhoneDisabled}
                />
              </Grid>
              <Grid item xs={6} sx={{ padding: '0px 5px' }}>
                <InputField
                  label={"Password"}
                  sx={{ margin: '10px 0px', width: '100%' }}
                  name="password"
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  InputProps={{
                    endAdornment: (
                      <InputAdornment position="end">
                        <IconButton onClick={() => setShowPassword(!showPassword)} edge="end">
                          <Iconify icon={showPassword ? 'eva:eye-fill' : 'eva:eye-off-fill'} />
                        </IconButton>
                      </InputAdornment>
                    ),
                  }}
                  onChange={(e) => setPassword(e.target.value)}
                />
              </Grid>
            </>
          }

          {signInChange === "Email" &&
            <>
              <Grid item xs={6} sx={{ padding: '0px 5px' }}>
                <InputField
                  label={"Email"}
                  sx={{ margin: '10px 0px', width: '100%' }}
                  type="email"
                  name="EmailAddress"
                  error={!!emailError}
                  helperText={emailError}
                  value={email}
                  onChange={handleMailChange}
                  disabled={isEmailDisabled}
                />
              </Grid>
              <Grid item xs={6} sx={{ padding: '0px 5px' }}>
                <InputField
                  label={"Password"}
                  sx={{ margin: '10px 0px', width: '100%' }}
                  name="password"
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  InputProps={{
                    endAdornment: (
                      <InputAdornment position="end">
                        <IconButton onClick={() => setShowPassword(!showPassword)} edge="end">
                          <Iconify icon={showPassword ? 'eva:eye-fill' : 'eva:eye-off-fill'} />
                        </IconButton>
                      </InputAdornment>
                    ),
                  }}
                  onChange={(e) => setPassword(e.target.value)}
                />
              </Grid>
            </>
          }


          {signInChange === "Email" ?
            <Grid item xs={6} sx={{ padding: '0px 5px', marginTop: "20px" }}>
              <button type="button" style={{ width: '100%', border: '1px solid #717171', borderRadius: '5px', backgroundColor: 'transparent', padding: '14px' }} onClick={() => SignIn({ type: 'Phone' })}>
                <p style={{ color: "#717171", marginBottom: '0px' }}>Continue with Phone</p>
              </button>
            </Grid>

            :

            <Grid item xs={6} sx={{ padding: '0px 5px', marginTop: "20px" }}>
              <button type="button" style={{ width: '100%', border: '1px solid #717171', borderRadius: '5px', backgroundColor: 'transparent', padding: '14px' }} onClick={() => SignIn({ type: 'Email' })}>
                <p style={{ color: "#717171", marginBottom: '0px' }}>  Continue with Email</p>
              </button>
            </Grid>
          }

          <Grid container justifyContent="center" sx={{ paddingTop: '20px' }}>
            <Button variant="contained" size="medium" color="primary" onClick={() => createAdmin()}>
              Create Account
            </Button>
          </Grid>
        </Card>
      </Modal>
    </>
  );
} 
